  (hR : ↑R ∈ rightTransversals ↑H) (hR1 : 1 ∈ R) (hS : closure ↑S = ⊤) :
  closure ↑(Finset.image (fun g => ⟨g * (↑(toFun hR g))⁻¹, ⋯⟩) (R * S)) = ⊤

